def trop_mv(A, x):
    n = A.shape[0]
    return np.array([np.max(A[i, :] + x) for i in range(n)])

def non_autonomous_bound(L, delta, n):
    total = 0.0
    for k in range(n):
        prod = 1.0
        for j in range(k+1, n):
            prod *= L[j]
        total += prod
    return delta * total

def certificate(L, delta):
    assert L < 1 and delta >= 0
    return {"radius": delta / (1 - L), "L": L, "delta": delta}
